package net.battlespades.bot;
import java.util.*;
import net.battlespades.physics.PlayerPhysics.Vector;
import static net.battlespades.bot.BotState.*;
import static net.battlespades.bot.BotSchematic.Placement;
import static net.battlespades.bot.ProjectSites.Column;
import static net.battlespades.bot.SchematicPlanning.*;
import static net.battlespades.bot.TeamTasks.Identity;
import static net.battlespades.bot.BotVectors.distance;
import static net.battlespades.bot.RecoveryPlanning.World;

/** Shared worker construction sites, step claims, builder limits and rejection feedback. */
public final class SchematicSites {
    public record KeepAway(Vector position,double radius){}public record Choice(Placement placement,Plan plan){}public record Claim(Identity builder,double until,Cell stand){}public record Claimed(Step step,Cell node){}
    public static final class Site {
        public final int id,team;public final Plan plan;public final String purpose;public final Identity owner;public final double createdAt,expiresAt,priority;public final String requester;public final Set<Integer> buildersAllowed;public Identity occupant;public final int maxBuilders;public final Region region;public final LinkedHashMap<Integer,Claim> claims=new LinkedHashMap<>();public final LinkedHashMap<Integer,Double> backoff=new LinkedHashMap<>();public final LinkedHashMap<Integer,Integer> failures=new LinkedHashMap<>();public final Set<Integer> skipped=new HashSet<>(),done=new HashSet<>();public final LinkedHashMap<Identity,Double> builders=new LinkedHashMap<>();public final LinkedHashMap<Integer,Integer> cellsByBuilder=new LinkedHashMap<>();public final ArrayDeque<Double> underFire=new ArrayDeque<>();public int linesBuilt,singlesBuilt,lineCells,singleCells,totalFailures;public double progressAt,completedAt;public String abandoned="";
        Site(int id,int team,Plan plan,String purpose,Identity owner,double now,double ttl,double priority,String requester,Set<Integer> allowed,Identity occupant){this.id=id;this.team=team;this.plan=plan;this.purpose=purpose;this.owner=owner;createdAt=now;expiresAt=now+ttl;this.priority=priority;this.requester=requester;buildersAllowed=Set.copyOf(allowed);this.occupant=occupant;maxBuilders=Math.max(1,plan.placement().schematic().maxBuilders());region=region(plan.placement());progressAt=now;}
        public String name(){return plan.placement().name();}public boolean active(){return abandoned.isEmpty()&&completedAt==0;}public Vector centre(){return position(plan.placement().anchor());}public Set<Cell> cells(){var cells=new HashSet<>(plan.placement().cells().keySet());cells.addAll(plan.placement().clear());return Set.copyOf(cells);}
        public Map<String,Object> status(World w){var r=new LinkedHashMap<String,Object>();r.put("site_id",id);r.put("name",name());r.put("team",team);r.put("purpose",purpose);var a=plan.placement().anchor();r.put("anchor",List.of(a.x(),a.y(),a.z()));r.put("rotation",plan.placement().rotation());r.put("steps",plan.steps().size());r.put("done",done.size());r.put("skipped",skipped.size());r.put("remaining_cells",w==null?null:cellsLeft(w,plan));r.put("lines_built",linesBuilt);r.put("singles_built",singlesBuilt);r.put("line_cells",lineCells);r.put("single_cells",singleCells);r.put("builders",cellsByBuilder.size());r.put("completed_at",completedAt);r.put("abandoned",abandoned);r.put("created_at",createdAt);return Collections.unmodifiableMap(r);}
    }
    private final Thread owner=Thread.currentThread();private final LinkedHashMap<Integer,Site> sites=new LinkedHashMap<>();private int nextId=1;private final Map<Integer,Double> teamReady=new HashMap<>();private final Map<String,Integer> metrics=new LinkedHashMap<>();private final ArrayDeque<Map<String,Object>> history=new ArrayDeque<>();private final Map<Integer,Integer> optionalCounts=new HashMap<>();
    void owned(){if(Thread.currentThread()!=owner)throw new IllegalStateException("Schematic sites outside worker");}void count(String key,int n){metrics.merge(key,n,Integer::sum);}
    public Map<Integer,Site> sites(){owned();return Collections.unmodifiableMap(sites);}public Map<String,Integer> metrics(){owned();return Collections.unmodifiableMap(new LinkedHashMap<>(metrics));}public List<Map<String,Object>> history(){owned();return List.copyOf(history);}public int optionalStarted(int team){owned();return optionalCounts.getOrDefault(team,0);}
    public void deferTeam(int team,double until){owned();teamReady.merge(team,until,Math::max);}
    public List<Site> activeSites(int team){owned();return sites.values().stream().filter(s->s.team==team&&s.active()).toList();}
    public boolean canStart(int team,double now,boolean optional,Vector at){owned();var active=activeSites(team);return active.size()<3&&sites.size()<8&&(!optional||now>=teamReady.getOrDefault(team,0.))&&(at==null||active.stream().noneMatch(s->distance(s.centre(),at)<10));}
    public Site create(int team,Plan plan,String purpose,Identity owner,double now,double ttl,double priority,String requester,Set<Integer> builders,Identity occupant,boolean optional){owned();if(!plan.feasible()||!canStart(team,now,optional,null))return null;evict();var s=new Site(nextId++,team,plan,purpose,owner,now,ttl,priority,requester,builders,occupant);sites.put(s.id,s);if(optional){teamReady.put(team,now+45);optionalCounts.merge(team,1,Integer::sum);}count("sites_started",1);count("sites_started:"+s.name(),1);return s;}
    public static Integer ground(World w,int x,int y,double near,int span){int expected=(int)Math.rint(near+2.25);var values=new ArrayList<Integer>();for(int s=expected-span;s<=expected+span;s++)values.add(s);values.sort(Comparator.comparingInt((Integer s)->Math.abs(s-expected)).thenComparingInt(s->s));for(int s:values)if(standable(w,new Cell(x,y,s)))return s;return null;}
    public static Set<Column> interior(Placement p){if(p.occupant()==null)return Set.of();int x=(int)Math.floor(p.occupant().x()),y=(int)Math.floor(p.occupant().y());int walls=p.schematic().cells().stream().mapToInt(c->Math.max(Math.abs(c.u()),Math.abs(c.f()))).max().orElseThrow(),limit=Math.max(1,walls-1);var result=new HashSet<Column>();for(var c:p.clear())if(c.z()==p.groundZ()-1&&Math.max(Math.abs(c.x()-x),Math.abs(c.y()-y))<=limit)result.add(new Column(c.x(),c.y()));return Set.copyOf(result);}
    public static Choice find(World w,BotSchematic shape,Vector at,Vector facing,boolean exact,boolean anyRotation,List<KeepAway> away,Set<Cell> reserved,List<Vector> bodies,Vector occupantBody,int maxCandidates,int seed){int cx=(int)Math.floor(at.x()),cy=(int)Math.floor(at.y()),preferred=BotSchematic.rotation(facing.x(),facing.y());var rotations=new ArrayList<Integer>();rotations.add(preferred);if(anyRotation){rotations.add((preferred+1)%4);rotations.add((preferred+3)%4);rotations.add((preferred+2)%4);}var offsets=new ArrayList<Column>();if(exact)offsets.add(new Column(0,0));else{for(int x=-3;x<=3;x++)for(int y=-3;y<=3;y++)offsets.add(new Column(x,y));offsets.sort(Comparator.comparingInt((Column c)->c.x()*c.x()+c.y()*c.y()).thenComparingInt(Column::x).thenComparingInt(Column::y));offsets=new ArrayList<>(offsets.subList(0,Math.min(maxCandidates,offsets.size())));}var bodySet=new HashSet<Cell>();for(var body:bodies){if(occupantBody!=null&&distance(body,occupantBody)<.5)continue;int top=(int)Math.floor(body.z());for(int x=(int)Math.floor(body.x()-.45);x<=(int)Math.floor(body.x()+.45);x++)for(int y=(int)Math.floor(body.y()-.45);y<=(int)Math.floor(body.y()+.45);y++)for(int z=top;z<top+3;z++)bodySet.add(new Cell(x,y,z));}record FitScore(double score,Placement placement){}var fits=new ArrayList<FitScore>();int attempts=0;for(var offset:offsets){int x=cx+offset.x(),y=cy+offset.y();var ground=ground(w,x,y,at.z(),3);if(ground==null)continue;for(int rotation:rotations){if(++attempts>maxCandidates*2)break;var p=shape.fit(w,new Column(x,y),ground,rotation,0).placement();if(p==null||!Collections.disjoint(p.cells().keySet(),reserved)||!Collections.disjoint(p.clear(),reserved)||!Collections.disjoint(p.cells().keySet(),bodySet)||away.stream().anyMatch(a->p.cells().keySet().stream().anyMatch(c->Math.hypot(c.x()+.5-a.position().x(),c.y()+.5-a.position().y())<a.radius())))continue;double score=Math.hypot(offset.x(),offset.y())+(rotation==preferred?0:1.5)+p.foundation().size()*.2;fits.add(new FitScore(score,p));}}fits.sort(Comparator.comparingDouble(FitScore::score));for(var f:fits.subList(0,Math.min(2,fits.size()))){var plan=plan(w,f.placement(),8,REACH,f.placement().occupant()!=null&&exact,seed,true);if(plan.feasible())return new Choice(f.placement(),plan);}return null;}
    public Site request(World w,int team,Object schematic,Vector at,double now,Vector facing,Integer rotation,boolean exact,String purpose,String requester,Set<Integer> builders,double priority,double ttl,Identity owner){owned();Plan plan;if(schematic instanceof Placement p)plan=plan(w,p,8,REACH,false,0,true);else{var shape=schematic instanceof String name?SchematicLibrary.get(name):(BotSchematic)schematic;if(shape==null)return null;if(rotation!=null){var ground=ground(w,(int)Math.floor(at.x()),(int)Math.floor(at.y()),at.z(),3);if(ground==null)return null;var placement=shape.fit(w,new Column((int)Math.floor(at.x()),(int)Math.floor(at.y())),ground,rotation,0).placement();plan=placement==null?null:plan(w,placement,8,REACH,false,0,true);}else{var choice=find(w,shape,at,facing,exact,true,List.of(),reserved(team,-1),List.of(),null,12,0);plan=choice==null?null:choice.plan();}}if(plan==null||!plan.feasible()){count("requests_rejected",1);return null;}var site=create(team,plan,purpose.isEmpty()?plan.placement().schematic().purpose():purpose,owner,now,ttl,priority,requester,builders,null,false);if(site!=null)count("requests_accepted",1);return site;}
    public void cancel(int id,String reason){owned();var site=sites.get(id);if(site!=null&&site.active())abandon(site,reason);}
    public Set<Cell> reserved(int team,int exclude){owned();var result=new HashSet<Cell>();for(var s:sites.values())if(s.team==team&&s.active()&&s.id!=exclude)result.addAll(s.cells());return Set.copyOf(result);}
    public void refresh(World w,double now,Map<TeamTasks.Observer,Integer> alive){owned();for(var s:sites.values()){if(!s.active())continue;for(int i=0;i<s.plan.steps().size();i++)if(!s.done.contains(i)&&remaining(w,s.plan.steps().get(i)).isEmpty()){s.done.add(i);s.claims.remove(i);s.progressAt=Math.max(s.progressAt,now-1e-6);}s.claims.values().removeIf(c->c.until()<=now||alive!=null&&!Objects.equals(alive.get(new TeamTasks.Observer(c.builder().id(),c.builder().generation())),c.builder().life()));s.builders.values().removeIf(t->now-t>=6);if(s.done.size()+s.skipped.size()>=s.plan.steps().size()){if(!s.skipped.isEmpty()&&s.done.size()<.85*s.plan.steps().size())abandon(s,"steps_rejected");else{s.completedAt=now;count("sites_completed",1);count("sites_completed:"+s.name(),1);record(s,"completed",now);}}else if(now>=s.expiresAt)abandon(s,"expired");else if(now-s.progressAt>45)abandon(s,"no_progress");}}
    void abandon(Site s,String reason){s.abandoned=reason;s.claims.clear();count("sites_abandoned",1);count("sites_abandoned:"+reason,1);record(s,"abandoned:"+reason,s.progressAt);}
    void record(Site s,String outcome,double now){var r=new LinkedHashMap<>(s.status(null));r.put("outcome",outcome);r.put("at",now);if(history.size()==64)history.removeFirst();history.addLast(Collections.unmodifiableMap(r));}
    void evict(){var finished=sites.values().stream().filter(s->!s.active()).sorted(Comparator.comparingDouble(s->s.completedAt!=0?s.completedAt:s.createdAt)).toList();for(var s:finished){if(sites.size()<8)break;sites.remove(s.id);}}
    public void forget(int id,int generation){owned();for(var s:sites.values())s.claims.values().removeIf(c->c.builder().id()==id&&c.builder().generation()==generation);}
    public Site siteFor(int team,int id,Vector at,boolean requestedOnly){owned();Site best=null;double distance=Double.POSITIVE_INFINITY;for(var s:sites.values()){if(s.team!=team||!s.active()||!s.buildersAllowed.isEmpty()&&!s.buildersAllowed.contains(id)||requestedOnly&&s.requester.isEmpty())continue;double d=distance(s.centre(),at);if(d>28)continue;var busy=new HashSet<TeamTasks.Observer>();for(var b:s.builders.keySet())busy.add(new TeamTasks.Observer(b.id(),b.generation()));if(busy.size()>=s.maxBuilders&&busy.stream().noneMatch(b->b.id()==id))continue;if(d<distance){best=s;distance=d;}}return best;}
    public Claimed claim(Site site,Identity builder,Vector at,World w,double now,List<Vector> others,boolean preferInside,int seed){owned();site.builders.put(builder,now);site.claims.values().removeIf(c->c.builder().equals(builder));var region=site.region;var avoidCells=new HashSet<Cell>();var avoidColumns=new HashSet<Column>();for(var e:site.claims.entrySet()){avoidCells.addAll(site.plan.steps().get(e.getKey()).cells());avoidColumns.add(new Column(e.getValue().stand().x(),e.getValue().stand().y()));}var otherBodies=new HashSet<Cell>();for(var b:others){var n=node(w,b);if(n!=null){otherBodies.addAll(body(n));avoidColumns.add(new Column(n.x(),n.y()));}else for(int z=(int)Math.floor(b.z());z<(int)Math.floor(b.z())+3;z++)otherBodies.add(new Cell((int)Math.floor(b.x()),(int)Math.floor(b.y()),z));}var start=node(w,at);var sources=start!=null&&region.contains(start.x(),start.y())?List.of(start):boundary(w,region);var distances=distances(w,region,sources,2048);if(start!=null&&region.contains(start.x(),start.y())&&distances.size()<=1)distances=distances(w,region,boundary(w,region),2048);var prefer=preferInside?site.plan.placement().occupant():null;var allowed=prefer!=null?interior(site.plan.placement()):null;record Ranked(double rank,int index,Step step){}var candidates=new ArrayList<Ranked>();for(int i=0;i<site.plan.steps().size();i++){var s=site.plan.steps().get(i);if(site.done.contains(i)||site.skipped.contains(i)||site.claims.containsKey(i)||site.backoff.getOrDefault(i,0.)>now||!ready(w,s)||s.cells().stream().anyMatch(otherBodies::contains))continue;var mid=s.cells().get(s.cells().size()/2);double rank=i*.6+distance(at,centre(mid))*.25;if(prefer!=null)rank+=Math.hypot(mid.x()+.5-prefer.x(),mid.y()+.5-prefer.y())*.8;candidates.add(new Ranked(rank,i,s));}candidates.sort(Comparator.comparingDouble(Ranked::rank).thenComparingInt(Ranked::index));var passes=new ArrayList<Set<Column>>();passes.add(allowed);if(allowed!=null&&start!=null&&allowed.contains(new Column(start.x(),start.y())))passes.addFirst(Set.of(new Column(start.x(),start.y())));avoidCells.addAll(otherBodies);for(var columns:passes)for(var c:candidates.subList(0,Math.min(6,candidates.size()))){var remain=remaining(w,c.step());var found=findStand(w,c.step().cells(),region,null,REACH,avoidCells,avoidColumns,columns,prefer,site.plan.placement().groundZ(),true,seed+c.index(),distances);if(found==null||remain.isEmpty())continue;site.claims.put(c.index(),new Claim(builder,now+9,found.node()));return new Claimed(c.step(),found.node());}return null;}
    public void extend(Site s,int index,Identity builder,double now){owned();var c=s.claims.get(index);if(c!=null&&c.builder().equals(builder))s.claims.put(index,new Claim(builder,now+9,c.stand()));}public void release(Site s,int index,Identity builder){owned();var c=s.claims.get(index);if(c!=null&&c.builder().equals(builder))s.claims.remove(index);}
    public void built(Site s,int index,Identity builder,int placed,double now){owned();var step=s.plan.steps().get(index);s.claims.remove(index);s.done.add(index);s.progressAt=now;if(step.line()){s.linesBuilt++;s.lineCells+=placed;count("lines_built",1);count("line_cells",placed);}else{s.singlesBuilt++;s.singleCells+=placed;count("singles_built",1);count("single_cells",placed);}s.cellsByBuilder.merge(builder.id(),placed,Integer::sum);}
    public void failed(Site s,int index,Identity builder,String reason,double now){owned();s.claims.remove(index);s.failures.merge(index,1,Integer::sum);s.totalFailures++;s.backoff.put(index,now+3*s.failures.get(index));count("steps_failed",1);count("steps_failed:"+reason,1);if(s.failures.get(index)>=5)s.skipped.add(index);if(s.totalFailures>=16)abandon(s,"too_many_rejections");}
    public boolean underFire(Site s,double now){owned();if(s.underFire.size()==16)s.underFire.removeFirst();s.underFire.addLast(now);if(s.underFire.stream().filter(t->now-t<=15).count()>=4&&s.active()){abandon(s,"under_fire");return true;}return false;}
}
